use serde_json::Value;
use super::{contract::*,nested_host_scope::*,names::*};
#[derive(Debug,Clone,Default)] pub struct KernelToolsCapability{pub capabilities:Option<KernelToolCapabilities>}
#[derive(Debug,Clone)] pub struct KernelToolGrant{pub capability:KernelToolsCapability,pub descriptors:Vec<KernelToolDescriptor>,pub requested_names:Vec<String>,pub scope:Option<KernelToolInvokeScope>}
#[derive(Debug,Clone)] pub struct KernelToolGrantRequest{pub requested_names:Vec<String>,pub capability:Option<KernelToolsCapability>,pub execution_mode:crate::manager::execution_mode::ExecutionMode,pub agent_type:Option<String>,pub team_role_member:bool,pub existing_tool_names:Vec<String>,pub tool_allowlist:Option<Vec<String>>,pub tool_denylist:Option<Vec<String>>}
#[derive(Debug,Clone)] pub enum KernelToolGrantResolution{None,Granted(KernelToolGrant),Denied{code:KernelToolErrorCode,message:String}}
pub fn resolve_kernel_tool_grant(r:&KernelToolGrantRequest, described:Option<&Value>)->KernelToolGrantResolution{if r.requested_names.is_empty(){return KernelToolGrantResolution::None} else if r.agent_type.as_deref().is_some_and(|name|crate::agents::curated_readonly_agent_names().contains(name)){return KernelToolGrantResolution::Denied{code:KernelToolErrorCode::CuratedPolicyDenied,message:"Curated agents cannot receive parent kernel tools.".into()}} else if r.team_role_member{return KernelToolGrantResolution::Denied{code:KernelToolErrorCode::ToolsUnavailable,message:"Team members run out of process and cannot reach a parent JavaScript kernel.".into()}} else if r.execution_mode!=crate::manager::execution_mode::ExecutionMode::InProcess{return KernelToolGrantResolution::Denied{code:KernelToolErrorCode::ToolsUnavailable,message:format!("Parent kernel tools require an in-process child; this child runs in {} mode.",r.execution_mode.as_str())}}let scope_req=NestedHostScopeRequest{child_tool_names:Some(r.existing_tool_names.clone()),tool_allowlist:r.tool_allowlist.clone(),tool_denylist:r.tool_denylist.clone(),include_task_tools:false};let escalating=if r.capability.as_ref().is_none_or(|x|!supports_invoke_scope(x.capabilities.as_ref())){escalating_host_tools(&scope_req)}else{Vec::new()};if !escalating.is_empty(){return KernelToolGrantResolution::Denied{code:KernelToolErrorCode::ToolsUnavailable,message:nested_host_scope_message("This child",&escalating)}}let missing_context=r.capability.is_none()&&described.is_none();if missing_context{return KernelToolGrantResolution::Denied{code:KernelToolErrorCode::ToolsUnavailable,message:"Kernel tools require a live JavaScript worker context; this parent invocation has none.".into()}}let mut names:Vec<String>=Vec::new();for n in &r.requested_names{let n=normalize_kernel_tool_name(n);if is_reserved_kernel_tool_name(&n)||r.existing_tool_names.iter().any(|x|kernel_tool_key(x)==kernel_tool_key(&n))||names.iter().any(|x|kernel_tool_key(x)==kernel_tool_key(&n)){return KernelToolGrantResolution::Denied{code:if is_reserved_kernel_tool_name(&n){KernelToolErrorCode::ReservedToolName}else{KernelToolErrorCode::ToolNameCollision},message:format!("Parent kernel tool name \"{n}\" collides with an existing tool.")}}names.push(n)}let entries=described.and_then(|v|parse_describe_results(v).ok()).unwrap_or_default();let mut ds=Vec::new();for e in entries{if !e.ok{return KernelToolGrantResolution::Denied{code:KernelToolErrorCode::KernelToolMissing,message:e.error.map(|x|x.message).unwrap_or_default()}} ds.extend(e.descriptor)}let cap=r.capability.clone().unwrap_or_default();KernelToolGrantResolution::Granted(KernelToolGrant{capability:cap,descriptors:ds,requested_names:names,scope:r.capability.as_ref().filter(|x|supports_invoke_scope(x.capabilities.as_ref())).map(|_|child_invoke_scope(&scope_req))})}
